head.script:
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        window.document.body.scroll = "no";
        let arrPar = new Array();
        const parentWin = $c.frame.path("../");
        scwin.fn_GetPar = parentWin.scwin.fn_GetPar;
        scwin.fn_SetPar = parentWin.scwin.fn_SetPar;
        if (scwin.fn_GetPar !== undefined) {
            scwin.fn_GetPar(arrPar);
        }
        txb_Search.focus();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05016.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name txb_Search_onkeydown
 * @description txb_Search 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_Search_onkeydown = async function() {
    try {
        if (event.keyCode === 13) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05016.txb_Search_onkeydown" });
    }
};

/**
 * @method
 * @name dts_OnLoadError
 * @description dts 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_OnLoadError = async function() {
    try {
        await $c.win.alert(dts);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05016.dts_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_OnLoadCompleted
 * @description dts 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts.errorMsg) {
            await $c.win.alert(dts.errorMsg);
        } else {
            txb_TotCnt.setValue("총 " + rowcount + " 건");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05016.dts_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_IsuInst_OnDblClick
 * @description grd_IsuInst 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_IsuInst_OnDblClick = async function(row, colid) {
    try {
        let arrPar = new Array();
        if (scwin.fn_SetPar !== undefined) {
            arrPar[0] = {
                ISU_CD: dts.getCellData(dts.getRowPosition(), "ISU_CD"),
                ISU_ENG_NM: dts.getCellData(dts.getRowPosition(), "ISU_ENG_NM")
            };
            scwin.fn_SetPar(arrPar);
        }
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05016.grd_IsuInst_OnDblClick" });
    }
};

/**
 * @method
 * @name img_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05016.img_Search_onclick" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05016.img_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "&inputMessageId=LISTSYNTHETFISU_INOUT&outputMessageId=LISTSYNTHETFISU_INOUT";
    url += "&ISU_KOR_NM=" + txb_Search.getValue();
    const sbmOptions = {
        id : "sbm_dts",
        action : "/SynthEtfTrctptInfo.do",
        ref : "",
        target : "dts=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
